        in(node->left);
        cout << node->info << ' ';
        in(node->right);
    }
    // POSTORDER: visit AFTER both subtrees (L R N).
    void post(TreeNode* node) const {
        if (node == nullptr) return;
        post(node->left);
        post(node->right);
        cout << node->info << ' ';
    }

