    bool isEmpty() const { return root == nullptr; }
    void clear() {
        destroy(root);
        root = nullptr; // Prevent a dangling root and allow reuse.
    }
    // Public wrappers start traversal at root; helpers handle subtrees.
    void preorder() const { pre(root); cout << '\n'; }
    void inorder() const { in(root); cout << '\n'; }
    void postorder() const { post(root); cout << '\n'; }
