    int info;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int value) : info(value), left(nullptr), right(nullptr) {}
};

// TREE: owns every node reachable from root.
class BST {
private:
    TreeNode* root; // nullptr means the tree is empty.

    // Return the root of the updated subtree so the caller can save its link.
    TreeNode* insertNode(TreeNode* node, int value) {
        if (node == nullptr) return new TreeNode(value); // Empty spot: create leaf.
        if (value < node->info)
            node->left = insertNode(node->left, value);
        else
            node->right = insertNode(node->right, value); // Equal values go RIGHT.
        return node; // Keep this subtree attached to its parent.
    }

    // POSTORDER cleanup: delete children before the parent that links to them.
    void destroy(TreeNode* node) {
        if (node == nullptr) return; // Base case: no node to delete.
        destroy(node->left);
        destroy(node->right);
        delete node; // Never read node after this line.
    }
    // Empty subtree contributes 0; each real node contributes 1.
    int nodes(TreeNode* node) const {
        if (node == nullptr) return 0;
        return 1 + nodes(node->left) + nodes(node->right);
    }
    // A leaf has NEITHER a left child nor a right child.
    int leaves(TreeNode* node) const {
        if (node == nullptr) return 0;
        if (node->left == nullptr && node->right == nullptr) return 1;
        return leaves(node->left) + leaves(node->right);
    }
    // Height counts EDGES: leaf = 0. Empty tree = -1 by our convention.
    int heightOf(TreeNode* node) const {
        if (node == nullptr) return -1;
        int leftHeight = heightOf(node->left);
        int rightHeight = heightOf(node->right);
        int taller = (leftHeight > rightHeight) ? leftHeight : rightHeight;
        return 1 + taller; // One edge from this node to its taller child.
    }

public:
    BST() : root(nullptr) {}
    // Owning raw pointers cannot safely use the default shallow copy.
    BST(const BST&) = delete;
    BST& operator=(const BST&) = delete;
    ~BST() { clear(); } // Automatically release all remaining nodes.

    void insert(int value) { root = insertNode(root, value); }
    bool isEmpty() const { return root == nullptr; }
    void clear() {
        destroy(root);
        root = nullptr; // Prevent a dangling root and allow reuse.
    }
    int countNodes() const { return nodes(root); }
    int countLeaves() const { return leaves(root); }
    int height() const { return heightOf(root); }
};

